import{_ as i,l as o,o as a,c as s,v as t,p,x as n,d as l,i as A,S as d}from"./chunks/framework.InCnrqk-.js";const L=JSON.parse('{"title":"DeepSeek Sparse Attention","description":"","frontmatter":{"title":"DeepSeek Sparse Attention","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/deepseek-sparse-attention.md","filePath":"llm/deepseek-sparse-attention.md","lastUpdated":1789023840000}'),h={name:"llm/deepseek-sparse-attention.md"};function k(m,e,S,c,x,_){const r=o("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="deepseek-sparse-attention" tabindex="-1">DeepSeek Sparse Attention <a class="header-anchor" href="#deepseek-sparse-attention" aria-label="Permalink to &quot;DeepSeek Sparse Attention&quot;">​</a></h1><div class="epigraph"><p>相对 V3.1-Terminus，V3.2 唯一的架构改动是通过续训引入 DeepSeek Sparse Attention。</p><footer>—— DeepSeek-AI, DeepSeek-V3.2, arXiv:2512.02556</footer></div><p><a href="/llm/native-sparse-attention">Native Sparse Attention</a> 与其 <a href="/llm/nsa-paper">原文笔记</a> 写的是 Yuan 等人 2025 年的 NSA：压缩块、选择块、滑窗三路，按块对齐硬件，从预训练起就走稀疏图。DeepSeek Sparse Attention（DSA）是另一条合同。它挂在 MLA 的 MQA 模式上，用轻量 Lightning Indexer 给每个查询打细粒度 token 分，再只对 top-\\(k\\) 条潜向量做精确注意力。V3.2 / V3.2-Exp 从 V3.1-Terminus 的 128K 检查点续训得到，不是从零训一套三路块稀疏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>长上下文的二次项同时卡住训练与推理。NSA 的回答是：可见键必须是连续块，否则 Tensor Core 吃不到。DSA 的回答是：判断「这格要不要」可以很便宜，真正的 MLA 只需在选中的 \\(k\\) 个条目上做。识别无关位置允许更低精度、更少头；对准选中位置仍用主模型精度。若把选择做成与 GQA/MLA 冲突的不规则 gather，稀疏只存在于纸面。</p><p>续训约束把设计空间收窄。V3.1-Terminus 已经是 MLA + MoE 的 685B 级骨干，不可能换成 NSA 的三路块结构而不改权重语义。DSA 必须作为「在已有 MLA 上加 indexer、把稠密注意力改成选 token」接进去，并且用与 128K 扩展相同的数据分布，才能和 Terminus 头对头比质量。</p><p><span class="marginnote">DSA 的 \\(k\\) 是 token 级配额（原文续训取 2048），NSA 的配额是「选中块数 × 块长」。一个对齐的是潜向量条目，一个对齐的是连续 KV 块。不要把两篇的加速比画在同一张缺少单位的图上。</span></p><h3 id="细粒度不是更碎的-nsa" tabindex="-1">细粒度不是更碎的 NSA <a class="header-anchor" href="#细粒度不是更碎的-nsa" aria-label="Permalink to &quot;细粒度不是更碎的 NSA&quot;">​</a></h3><p>NSA 选择支路展开的是整块原始 token，压缩支路仍扫块目录。DSA 没有「先看目录再翻页」的三路融合：indexer 对每个过去位置出标量分，top-\\(k\\) 直接取条目。更碎意味着更难靠连续加载吃满带宽，因此实现必须让每条 KV 条目被该 token 的全部查询头共享——这正是 MLA 的 MQA 模式：潜向量跨头共享，选择才不会在头之间变成并集爆炸。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="lightning-indexer" tabindex="-1">Lightning Indexer <a class="header-anchor" href="#lightning-indexer" aria-label="Permalink to &quot;Lightning Indexer&quot;">​</a></h3><p>对查询 token \\(h_t\\) 与过去位置 \\(h_s\\)，indexer 分数为</p> \\[I_{t,s}=\\sum_{j=1}^{H^I} w_{t,j}^{I}\\cdot\\mathrm{ReLU}\\bigl(q_{t,j}^{I}\\cdot k_{s}^{I}\\bigr). \\]<p>头数 \\(H^I\\) 很小，\\(q^I,k^I\\) 维度 \\(d^I\\) 也小，激活用 ReLU 换吞吐，计算走 FP8。它仍是对过去长度的二次扫描，但常数远小于 MLA。选出 top-\\(k\\) 后，主注意力只在对应潜向量 \\(\\{c_s\\}\\) 上做：</p> \\[u_t=\\mathrm{Attn}\\bigl(h_t,\\{\\,c_s\\mid I_{t,s}\\in\\mathrm{Top}\\text{-}k(I_{t,:})\\,\\}\\bigr). \\]<p>主路径复杂度从 \\(O(L^2)\\) 落到 \\(O(Lk)\\)。Indexer 仍 \\(O(L^2)\\)，作者的论点是它比原来的 MLA 便宜得多，端到端在长上下文上仍降费。</p><h3 id="两段续训" tabindex="-1">两段续训 <a class="header-anchor" href="#两段续训" aria-label="Permalink to &quot;两段续训&quot;">​</a></h3><p>稠密热身：冻结骨干，只训 indexer。把主注意力各头分数求和，再沿序列做 L1 归一得到目标 \\(p_{t,:}\\)，用</p> \\[\\mathcal{L}^{I}=\\sum_t \\mathrm{KL}\\bigl(p_{t,:}\\,\\|\\,\\mathrm{softmax}(I_{t,:})\\bigr) \\]<p>对齐。学习率 \\(10^{-3}\\)，1000 步，每步 16 条 128K，共约 21 亿 token。</p><p>稀疏阶段：打开 top-\\(k\\)（\\(k=2048\\)），解冻全部参数。KL 只在选中集合 \\(S_t\\) 上算。Indexer 输入从主图拆开：indexer 只吃 \\(\\mathcal{L}^{I}\\)，骨干只吃语言建模损失。学习率 \\(7.3\\times 10^{-6}\\)，15000 步，每步 480 条 128K，共约 9437 亿 token。数据分布与 Terminus 的 128K 扩展对齐，便于公平比。</p>',21)),(a(),p(d,null,{default:n(()=>[A(r,{id:"mermaid-55",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E9%9A%90%E7%8A%B6%E6%80%81%22%5D%20--%3E%20IDX%5B%22Lightning%20Indexer%20FP8%22%5D%0A%20%20H%20--%3E%20MLA%5B%22MLA%20%E6%BD%9C%E5%90%91%E9%87%8F%22%5D%0A%20%20IDX%20--%3E%20TOP%5B%22top-k%20%E6%9D%A1%E7%9B%AE%22%5D%0A%20%20MLA%20--%3E%20TOP%0A%20%20TOP%20--%3E%20ATT%5B%22%E7%B2%BE%E7%A1%AE%E6%B3%A8%E6%84%8F%E5%8A%9B%20k%20%E2%89%AA%20L%22%5D%0A%20%20ATT%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="选择与主干为什么要拆梯度" tabindex="-1">选择与主干为什么要拆梯度 <a class="header-anchor" href="#选择与主干为什么要拆梯度" aria-label="Permalink to &quot;选择与主干为什么要拆梯度&quot;">​</a></h3><p>若让语言建模损失直接穿过离散 top-\\(k\\)，选择要么不可微，要么用直通把噪声送进 indexer。KL 对齐把「模仿稠密注意力的质量分布」当成 indexer 的显式目标：热身阶段学满分布，稀疏阶段只在已选项上校准，避免对未选项乱推。拆图则防止 indexer 为了短期 LM 损失塌成总选近邻。这与 NSA 用压缩支路 softmax 当块重要性、选择本身仍离散，是同一类「建议可训、离散不可微」结构，只是建议器一个是块压缩，一个是 token indexer。</p><p>短前填可以用掩码 MHA 模拟 DSA，因为 \\(L\\) 不大时 indexer + gather 的开销盖过稀疏收益。服务部署按 token 位置报 H800 上的费用曲线：长度上去之后，前填与解码相对 Terminus 明显下降。质量合同写的是：标准榜与 Arena Elo 与 Terminus 接近；独立长上下文评测（AA-LCR、Fiction.liveBench）上 V3.2-Exp 不差甚至更好。不要把 IMO/IOI 金牌写进 DSA 头上——那是后训练与 Speciale 变体的计算，不是稀疏核单独完成的。</p><p><span class="marginnote">V3.2 报告里的后训练（GRPO、智能体合成）与 DSA 正交。架构故事到「续训加入 indexer + top-k」为止。把 Speciale 的竞赛分数算成稀疏注意力的增益，是张冠李戴。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>\\(k=2048\\) 绑在 128K 续训设置上。更长上下文若不加大 \\(k\\)，检索容量可能不够；加大 \\(k\\) 就把 \\(O(Lk)\\) 往回推。Indexer 仍二次，极端长度会重新成为瓶颈，那时才需要再分级或改成 NSA 式块目录。实现若按头独立选 token，MLA 的共享条目被破坏，装载量回到并集，费用账作废。</p><p>与 NSA 的选用：从零训、要块对齐融核、要压缩目录，走 NSA；已有 MLA 检查点、要细粒度、要续训少改结构，走 DSA。两者都声称原生可训，但可训的对象不同：NSA 是三路块图，DSA 是 indexer 分布加稀疏 MLA。FlashAttention 式稠密核、Ring Attention 切序列，与这两条都正交。</p><p>开源复现需要 indexer 核与稀疏 MLA 核，而不是只在 PyTorch 里 <code>gather</code>。短序列走稠密模拟是原文就承认的分叉，评测延迟必须声明长度。</p><p>服务费用曲线按 token 位置画，前填与解码分开。短前填走掩码 MHA 模拟时，费用可能短暂高于 Terminus 的稠密 MLA，因为多了一条 indexer 路径却吃不到稀疏。越过交叉点之后，\\(O(Lk)\\) 才主导。部署若用单一核硬套所有长度，会在短请求上赔钱。\\(k\\) 在续训里固定，服务期若按负载动态改 \\(k\\)，质量合同作废：索引器是按 2048 的选中集做 KL 的，改配额等于改稀疏图。</p><p>与固定模式稀疏（滑窗、Longformer）相比，DSA 的边集随查询变，同一文档里不同位置会选不同过去 token。这保留了内容寻址，也保留了「选错就永远看不见」的失败模式：证据落在 top-\\(k\\) 之外且 indexer 没打出高分，针测或长文档问答会漏。热身只用 21 亿 token 对齐分布，不能保证 indexer 在续训分布之外的任务上仍模仿主注意力。独立评测用未见长上下文集，是在测这种泛化，不是在测稀疏公式本身。</p><p><span class="marginnote">不要写成「DeepSeek-V3 已默认 DSA」。V3 是 MLA 故事；DSA 从 V3.2-Exp / V3.2 才进入骨干。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DSA 用轻量 FP8 indexer 打 token 分，再对 top-\\(k\\) 潜向量做 MLA，主注意力从 \\(O(L^2)\\) 降到 \\(O(Lk)\\)。</li><li>它挂在 MLA 的 MQA 模式上，条目跨查询头共享，避免 GQA 式选择并集。</li><li>从 V3.1-Terminus 续训：先对齐 indexer，再稀疏训练约 9.4×10<sup>11</sup> token，\\(k=2048\\)。</li><li>与 NSA 的三路块稀疏互补：一个细粒度选 token，一个硬件对齐选块。</li><li>榜上与 Terminus 接近，长上下文费用下降；竞赛成绩属于后训练，不属于本核。</li><li>Indexer 仍二次，短序列可能退回掩码 MHA 模拟。</li><li>出处：DeepSeek-AI，<em>DeepSeek-V3.2: Pushing the Frontier of Open Large Language Models</em>，arXiv:2512.02556；NSA 对照 Yuan et al.，ACL 2025。</li></ul>',14))])}const D=i(h,[["render",k]]);export{L as __pageData,D as default};
